// path-deviation: between a line and an arc with the same ends
export function c005(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(20, 0) * millimeter });
    skArc(s1, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(10, 4) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(s1);
    const deviation = evMaxPathDeviation(context, { "side1" : sketchEntityQuery(id + "s1", EntityType.EDGE, "l1"), "side2" : sketchEntityQuery(id + "s1", EntityType.EDGE, "a1") });
    return { "deviation" : roundToPrecision(deviation.deviation / millimeter, 6), "side1" : mapArray(deviation.side1Point, function(x) { return roundToPrecision(x / millimeter, 6); }), "side2" : mapArray(deviation.side2Point, function(x) { return roundToPrecision(x / millimeter, 6); }) };
}

