// cutlist: the two tubes of a mitred L, and its table
export function c013(context is Context, id is Id)
{
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(path, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skLineSegment(path, "l2", { "start" : vector(100, 0) * millimeter, "end" : vector(100, 60) * millimeter });
    skSolve(path);
    frame(context, id + "frame1", { "profileSketch" : profileOf(squareTube), "selections" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
    cutlist(context, id + "cutlist1", { "selectAllFrames" : false, "frames" : qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID) });
    return { "composites" : evaluateQueryCount(context, qBodyType(qCreatedBy(id + "cutlist1", EntityType.BODY), BodyType.COMPOSITE)), "table" : caseTables(context, id, cutlistTable(context, {})) };
}

// hole-table: two simple holes and a counterbored one in a block
export function c014(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    const pts1 = newSketchOnPlane(context, id + "pts1", { "sketchPlane" : plane(vector(0, 0, 12) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPoint(pts1, "p1", { "position" : vector(10, 10) * millimeter });
    skPoint(pts1, "p2", { "position" : vector(30, 10) * millimeter });
    skSolve(pts1);
    const pts2 = newSketchOnPlane(context, id + "pts2", { "sketchPlane" : plane(vector(0, 0, 12) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPoint(pts2, "p1", { "position" : vector(20, 22) * millimeter });
    skSolve(pts2);
    hole(context, id + "hole1", { "locations" : qOwnedByBody(qBodyType(qCreatedBy(id + "pts1", EntityType.BODY), BodyType.POINT), EntityType.VERTEX), "scope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "style" : HoleStyle.SIMPLE, "holeDiameter" : 4 * millimeter, "holeDepth" : 6 * millimeter, "endStyle" : HoleEndStyle.BLIND });
    hole(context, id + "hole2", { "locations" : qOwnedByBody(qBodyType(qCreatedBy(id + "pts2", EntityType.BODY), BodyType.POINT), EntityType.VERTEX), "scope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "style" : HoleStyle.C_BORE, "holeDiameter" : 6 * millimeter, "cBoreDiameter" : 10 * millimeter, "cBoreDepth" : 4 * millimeter, "endStyle" : HoleEndStyle.THROUGH });
    return { "table" : caseTables(context, id, holeTable(context, {})) };
}
